/**
 * Refuse a load above what the rules allow: in a deload, above the deload
 * target; on a stalled lift, above the stall ladder's target.
 * @returns {string|null} the reason, or null when the load is fine
 */
function progressionGuard({ workouts, exercise, weight, unit = 'lbs', plates = null, repTarget = null, intent = null }) {
    if (typeof weight !== 'number' || !exercise) return null;
    const sessions = exerciseSessions(workouts, exercise, unit);
    const t = progressionTarget(sessions, unit, repTarget, weightIncrement(unit, plates), intent);
    if (!t || weight <= t.weight + 0.01) return null;
    if (t.action === 'deload') {
        return `Deload: ${exercise}'s target this session is ${t.weight} ${unit}${t.reps ? `×${t.reps}` : ''} — ${weight} goes above it. Hold or reduce.`;
    }
    if (t.stalled) {
        return `${exercise} is on stall rung ${t.rung} (${t.stallRun} sessions flat at ${sessions[0].topWeight} ${unit}); the rule's target is ${t.weight} ${unit}${t.reps ? `×${t.reps}` : ''} (${t.action}) — ${weight} contradicts it.`;
    }
    return null;
}

/**
 * Refuse a weight the gym can't build: it must sit a whole number of
 * smallest-jumps away from a weight already lifted on this exercise (the
 * scaleLoadableWeight rule). No history → nothing to anchor to → allowed.
 * @returns {string|null}
 */
function loadabilityGuard({ workouts, exercise, weight, unit = 'lbs', plates = null }) {
    if (typeof weight !== 'number' || weight <= 0 || !exercise) return null;
    const lifted = exerciseSessions(workouts, exercise, unit, { excludeRecovery: false })
        .map(s => s.topWeight).filter(w => w > 0);
    if (!lifted.length) return null;
    const inc = weightIncrement(unit, plates);
    const onGrid = (ref) => {
        const steps = (weight - ref) / inc;
        return Math.abs(steps - Math.round(steps)) < 0.02;
    };
    if (lifted.some(onGrid)) return null;
    const ref = lifted[0];
    const below = Math.round((ref + Math.floor((weight - ref) / inc) * inc) * 10) / 10;
    const above = Math.round((below + inc) * 10) / 10;
    return `${weight} ${unit} isn't loadable for ${exercise}: move in ${inc} ${unit} steps from a weight already lifted (last ${ref}) — e.g. ${below} or ${above}.`;
}

// ── Equipment resolution (AP-18) ────────────────────────────────────

/**
 * Resolve an equipment name against the user's library: exact
 * (case-insensitive) or Dice ≥ threshold → the library's canonical name;
 * else the three nearest names so the model can pick one.
 * @param {string} name
 * @param {string[]} library - equipment names
 * @returns {{ok:true, name:string, exact:boolean} | {ok:false, nearest:string[]}}
 */
function resolveEquipment(name, library, threshold = EQUIPMENT_MATCH_THRESHOLD) {
    const names = [...new Set((library || []).filter(Boolean))];
    const exact = names.find(n => norm(n) === norm(name));
    if (exact) return { ok: true, name: exact, exact: true };
    const scored = names.map(n => ({ n, s: diceSimilarity(name, n) })).sort((a, b) => b.s - a.s);
    if (scored[0] && scored[0].s >= threshold) return { ok: true, name: scored[0].n, exact: false };
    return { ok: false, nearest: scored.slice(0, 3).map(x => x.n) };
}

// ── Near-duplicate templates (AP-18) ────────────────────────────────

function jaccard(a, b) {
    const A = new Set((a || []).map(norm).filter(Boolean));
    const B = new Set((b || []).map(norm).filter(Boolean));
    if (!A.size || !B.size) return 0;
    let inter = 0;
    for (const x of A) if (B.has(x)) inter += 1;
    return inter / (A.size + B.size - inter);
}

/**
 * The active template whose exercise set overlaps `exercises` most, when
 * the overlap is ≥ threshold.
 * @returns {{templateId:string, name:string, overlap:number}|null}
 */
function findNearDuplicate(exercises, templates, threshold = NEAR_DUPLICATE_JACCARD) {
    const mine = (exercises || []).map(e => e?.machine || e?.name);
    let best = null;
    for (const t of templates || []) {
        if (!t || t.archived || t.isHidden || !Array.isArray(t.exercises)) continue;
        const overlap = jaccard(mine, t.exercises.map(e => e?.machine || e?.name));
        if (overlap >= threshold && (!best || overlap > best.overlap)) {
            best = { templateId: t.id, name: t.name || t.id, overlap: Math.round(overlap * 100) / 100 };
        }
    }
    return best;
}

// ── Program shape (AP-17) ───────────────────────────────────────────

const MAJOR_PARTS = ['Chest', 'Back', 'Legs', 'Shoulders'];
const DAY_KEYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];

/**
 * A program a trainer would sign off on: a block of 4+ weeks ends in a
 * deload (error); a week plan that hits a major muscle less than twice a
 * week, or a block whose training weeks are all identical, gets a warning.
 * @param {object} args
 * @param {number} args.weeks
 * @param {Array} args.weekTargets - normalized targets
 * @param {object|null} [args.split] - day → templateId | 'rest' | null
 * @param {Array} [args.templates] - [{id, exercises}] to resolve the split
 * @param {Array} [args.exerciseDatabase] - for body-part lookup
 * @returns {{error:string|null, warnings:Array<{code:string, message:string}>}}
 */
function programShapeIssues({ weeks, weekTargets = [], split = null, templates = [], exerciseDatabase = [] }) {
    const warnings = [];
    if (weeks >= 4 && !(weekTargets || []).some(isDeloadTarget)) {
        return {
            error: `A ${weeks}-week block needs a deload week — add a weekTarget with a negative weightPct and/or setDelta (usually the last week).`,
            warnings,
        };
    }
    if (weeks >= 3) {
        const shapes = new Set();
        for (let w = 1; w <= weeks; w++) {
            const t = (weekTargets || []).find(x => x.week === w);
            if (t && isDeloadTarget(t)) continue;
            const fx = weekTargetEffects(t);
            shapes.add(JSON.stringify([fx.weightPct, fx.setDelta, fx.repRange, fx.rpeTarget]));
        }
        if (shapes.size <= 1) {
            warnings.push({
                code: 'identical_weeks',
                message: 'Every training week is identical — give the block a shape (ramp setDelta, descend repRange, tighten rpeTarget).',
            });
        }
    }
    if (split && typeof split === 'object') {
        const byId = new Map((templates || []).map(t => [t.id, t]));
        const days = DAY_KEYS.map(d => split[d]).filter(id => id && id !== 'rest' && byId.has(id));
        if (days.length) {
            const freq = Object.fromEntries(MAJOR_PARTS.map(p => [p, 0]));
            for (const id of days) {
                const parts = new Set((byId.get(id).exercises || [])
                    .map(e => getBodyPartForExercise(e, exerciseDatabase))
                    .filter(Boolean));
                for (const p of parts) if (p in freq) freq[p] += 1;
            }
            for (const p of MAJOR_PARTS) {
                if (freq[p] < 2) {
                    warnings.push({
                        code: 'frequency',
                        message: `${p} is trained ${freq[p]}× a week in this split — most muscles grow best at 2×.`,
                    });
                }
            }
        }
    }
    return { error: null, warnings };
}

